//
// ElvenWoodSpecialPower::finish, retail RVA 0x0025C220, 1152 bytes.
//
// Identity.  The matched caller
// game/GameEngine/Source/GameLogic/Object/SpecialPower/
// ElvenWoodSpecialPowerDoSpecialPowerAtLocation.cpp (retail 0x0025CAA0, the
// doSpecialPowerAtLocation override of ElvenWoodSpecialPowerInterface)
// reaches this body through the ILT thunk 0x0003E757, whose ledger pin is
// ?finish@ElvenWoodSpecialPower@@QAEXPAVSpecialPowerLocation@@@Z, and the
// body ends in `ret 4`, so it takes exactly that one pointer.  The receiver
// is the ElvenWoodSpecialPower module: +0x04 is the module data (the caller
// reads the module data's name token at +0x21C through it) and +0x08 is the
// Object.  The shipped random-site string in the neighbouring body
// Rva0025C7C0ElvenWoodChoice.cpp pins the file:
// "F:\bfme\Code\gameengine\Source\GameLogic\Object\SpecialPower\
//  ElvenWoodSpecialPower.cpp", line 232, which is after this body.
//
// Structure.  Every frame slot the body touches is accounted for; offsets
// are from the top of the `sub esp,0xB8` block (the tracker's F):
//
//   F+0x10  BfmeWideResult   first PartitionManager result
//   F+0x14  Real             m_moduleData->m_radius, the float at +0x224
//   F+0x18  Object *         the loop variable, later the second result slot
//   F+0x1C  ModuleData *     m_moduleData  (this + 4)
//   F+0x20  Object *         m_object      (this + 8)
//   F+0x24  12 bytes         second kind mask, then a Coord3D, then the
//                            three-word status BitFlags
//   F+0x3C  24 bytes         first kind mask, later the heap set pointer
//   F+0x54  this
//   F+0x58  PartitionFilterAcceptByKindOf   (0x38 bytes)
//   F+0x90  PartitionFilterAcceptByKindOf   (0x38 bytes)
//   F+0xD0  the `push -1` slot: MSVC 7.1's /EHsc unwinding state byte
//
// Both filters take the same mask -- bit 51 (dword 4 = 0x800000) set, all
// else clear -- and KINDOFMASK_NONE (0x012ED8B8) as must-be-clear, and both
// come from the out-of-line constructor 0x000C3DD0 (ILT 0x000382FD) that
// copies two 24-byte masks to +0x08 and +0x20.  The two partition queries
// are radius*2.1 (0x010B4BCC) and radius*4.0 (0x01075340); the closing taint
// circle is radius+50.0 (0x0107FAA8).  Nothing in the binary names bit 51
// or the 0x80000 status bit the per-object test uses, so both stay
// address-derived here rather than guessed at.

#include <bitset>
#include <set>
#include <vector>
#include "ascii_string.h"

typedef int Int;
typedef unsigned int UnsignedInt;
typedef float Real;
typedef bool Bool;

// The bit the kind filter requires and the status test forbids.  Bit 51 of a
// 192-bit KindOfMaskType is dword 4 bit 19; the 0x80000 the status mask and
// Object+0x98 test use is the same bit in a 96-bit mask.
enum
{
	RVA_0025C220_KIND_BIT = 147,
	RVA_0025C220_STATUS_BIT = 83
};

//----------------------------------------------------------------------------
// BFME BitFlags, spelled as game/GameEngine/Source/GameLogic/ScriptEngine/
// ScriptConditions.cpp does for the same 192-bit KindOfMaskType that
// ?KINDOFMASK_NONE is pinned to.  A 96-bit instantiation is what
// Object::setStatus takes.
//----------------------------------------------------------------------------
template <int NUMBITS>
class BitFlags
{
	_STL::bitset<NUMBITS> m_bits;

public:
	enum BogusInitType { kInit = 0 };

	BitFlags(BogusInitType, Int idx1, Int idx2)
	{
		m_bits._Unchecked_set((size_t)idx1);
		m_bits._Unchecked_set((size_t)idx2);
	}
};

typedef BitFlags<192> KindOfMaskType;
typedef BitFlags<96> StatusMaskType;

struct Coord3D
{
	float x;
	float y;
	float z;
};

struct Matrix3D
{
	int m_unknown[9];
};

class Object;
class Player;
class FXList;
class BfmeTaintManager;
class Rva0025C220TerrainLogic;
class Rva0025C220ThingFB;
class GameLogic;
class Rva0025C7C0Location;

//----------------------------------------------------------------------------
// The owning-result partition iterator, byte for byte the shape the matched
// body PlayerHealSpecialPower::doSpecialPowerAtObject (0x00263CA0) proves:
// an owning std::vector of 8-byte entries plus a cursor and a reference
// count, wrapped in a class with a hand-written copy constructor and
// destructor and no assignment operator, so MSVC 7.1 synthesises the
// destroy-then-copy assignment whose self test is `lea ecx,[F+0x10];
// cmp ecx,esi` after the second query.
//----------------------------------------------------------------------------
struct BfmeWideEntry
{
	Object *object;
	UnsignedInt unknown04;
};

struct BfmeWideData
{
	std::vector<BfmeWideEntry> entries;
	BfmeWideEntry *current;
	Int references;
};

struct BfmeWideResult
{
	BfmeWideData *value;

	BfmeWideResult(const BfmeWideResult &other)
		: value(other.value)
	{
		++value->references;
	}
	~BfmeWideResult()
	{
		if (--value->references == 0)
			delete value;
	}

	Object *next(Object *&object)
	{
		if (value->current == value->entries.end())
			return 0;
		object = value->current->object;
		++value->current;
		return object;
	}
};

class BfmeWideForwardC
{
public:
	BfmeWideResult bfmeForwardWideC(Int position, Real range, Int order,
		Int filterHead, Bool mustBeValid);
};

// The three radius constants the body reads, and the two singletons it
// reaches the taint manager and the FX list through.
extern const Real BfmeRva0025C220RangeScale;    // 0x010B4BCC = 2.1
extern const Real BfmeRva0025C220TaintScale;    // 0x01075340 = 4.0
extern const Real BfmeRva0025C220TaintMargin;   // 0x0107FAA8 = 50.0

extern BfmeWideForwardC *ThePartitionManager;
extern const KindOfMaskType KINDOFMASK_NONE;
extern Rva0025C220TerrainLogic *TheTerrainLogic;
extern GameLogic *TheGameLogic;
extern BfmeTaintManager *TheTaintManager;

class FXList
{
public:
	Bool bfmeIsBlocked() const;
	void doFXPos(const Coord3D *position, const Matrix3D *a,
		const Matrix3D *b, Int mode) const;
};

class BfmeTaintManager
{
public:
	void bfmeApplyCircleWorld(const Coord3D *centre, Real range,
		unsigned char tint, Bool permanent);
};

class GameLogic
{
public:
	void destroyObject(Object *object);
};

class Rva0025C220ThingFB
{
public:
	void tellFB(Object *owner, const Coord3D *position, void *a, void *b);
};

// The terrain singleton's clearOne (ILT 0x000017CB -> 0x001AC3D0, pinned
// ?clearOne001AC3D0@TerrainArea001ACCC0@@QAEXPBXH@Z) plus the two three-
// int thunks the body calls after the sweeps: 0x00042CD0 -> 0x001A64F0 and
// 0x00037330 -> 0x001A3190, both `ret 0xC`.
class Rva0025C220TerrainLogic
{
public:
	void clearOne001AC3D0(void *position, unsigned short rangeBits);
	void adapter001A64F0(Int position, Int range, Int order);
	void forward001A3190(Int position, Int flag, Real range, Int order);
};

//----------------------------------------------------------------------------
// The BFME partition filters, spelled as
// game/GameEngine/Source/GameLogic/ScriptEngine/ScriptConditions.cpp does:
// vtable 0x01083B70 belongs to PartitionFilterAcceptByKindOf, whose
// out-of-line constructor copies the two 24-byte masks.
//----------------------------------------------------------------------------
class PartitionFilter
{
public:
	PartitionFilter() : m_next(0) {}
	virtual ~PartitionFilter() {}
	virtual Bool allow(Object *) = 0;
	virtual Int getPlayerMask();

	PartitionFilter *m_next;
};

class PartitionFilterAcceptByKindOf : public PartitionFilter
{
public:
	PartitionFilterAcceptByKindOf(const KindOfMaskType &mustBeSet,
		const KindOfMaskType &mustBeClear)
		: m_mustBeSet(mustBeSet), m_mustBeClear(mustBeClear) {}
	virtual ~PartitionFilterAcceptByKindOf() {}
	virtual Bool allow(Object *);

	KindOfMaskType m_mustBeSet;
	KindOfMaskType m_mustBeClear;
};

//----------------------------------------------------------------------------
// The Object fields the body witnesses: +0x38 is the position handed to
// clearOne and to the taint circle, +0x98 carries the status bit.
//----------------------------------------------------------------------------
class Object
{
public:
	Player *getControllingPlayer() const;
	void setStatus(const StatusMaskType &status, Bool on);

	unsigned char m_pad00[0x38];
	Coord3D m_position;
	unsigned char m_pad44[0x54];
	UnsignedInt m_statusFlags;
};

//----------------------------------------------------------------------------
// The module data: +0x21C the template name the lookup at 0x0025C010 takes,
// +0x224 the radius, +0x228 the FX list, +0x22C the thing-FX list.
//----------------------------------------------------------------------------
struct ElvenWoodSpecialPowerModuleData
{
	unsigned char m_pad00[0x21c];
	AsciiString m_templateName;
	unsigned char m_pad220[4];
	Real m_radius;
	FXList *m_fxList;
	Rva0025C220ThingFB *m_thingFB;
};

// A SpecialPowerLocation leads with its position: the body passes the
// location itself wherever a Coord3D * is expected.  It is a class, not a
// struct: the pinned ILT spells the argument `PAVSpecialPowerLocation`.
class SpecialPowerLocation
{
public:
	Coord3D m_position;
};

// The template lookup at 0x0025C010, pinned
// ?applyAt0025C010@Rva0025C7C0Owner@@QAEPAXPAVRva0025C7C0Location@@
// ABVAsciiString@@@Z; the neighbouring body calls it on the same receiver.
class Rva0025C7C0Owner
{
public:
	void *applyAt0025C010(Rva0025C7C0Location *location,
		const AsciiString &name);
};

//----------------------------------------------------------------------------
class ElvenWoodSpecialPower : public Rva0025C7C0Owner
{
public:
	void finish(SpecialPowerLocation *subject);

private:
	ElvenWoodSpecialPowerModuleData *m_moduleData;   // this + 4
	Object *m_object;                                // this + 8
};

// Every callee here is reached through an ILT thunk in retail, so each
// declaration below is redirected to the thunk the body actually calls.
#pragma comment(linker, "/alternatename:?getControllingPlayer@Object@@QBEPAVPlayer@@XZ=?j_00020824@@YAXXZ")
#pragma comment(linker, "/alternatename:?setStatus@Object@@QAEXABV?$BitFlags@$0FG@@@_N@Z=?j_000307E7@@YAXXZ")
#pragma comment(linker, "/alternatename:?destroyObject@GameLogic@@QAEXPAVObject@@@Z=?j_0001D0DE@@YAXXZ")
#pragma comment(linker, "/alternatename:?doFXPos@FXList@@QBEXPBUCoord3D@@PBVMatrix3D@@M0@Z=?j_0001BB21@@YAXXZ")
#pragma comment(linker, "/alternatename:?bfmeIsBlocked@FXList@@QBE_NXZ=?j_00011F77@@YAXXZ")
#pragma comment(linker, "/alternatename:?bfmeApplyCircleWorld@BfmeTaintManager@@QAEXPBUBfmePointFC@@MH_N@Z=?j_0008810D0@@YAXXZ")
#pragma comment(linker, "/alternatename:?adapter001A64F0@Rva0025C220TerrainLogic@@QAEXHHH@Z=?j_00042cd0@@YAXXZ")
#pragma comment(linker, "/alternatename:?forward001A3190@Rva0025C220TerrainLogic@@QAEXHHH@Z=?j_00037330@@YAXXZ")
#pragma comment(linker, "/alternatename:?tellFB@Rva0025C220ThingFB@@QAEXPAXPAXPAX0@Z=?j_00002a59@@YAXXZ")

// ?finish@ElvenWoodSpecialPower@@QAEXPAVSpecialPowerLocation@@@Z
// retail 0x0025C220
void ElvenWoodSpecialPower::finish(SpecialPowerLocation *subject)
{
	ElvenWoodSpecialPowerModuleData *const data = m_moduleData;
	Object *const owner = m_object;
	Real const range = data->m_radius;

	// First sweep: everything the wider circle holds that belongs to another
	// player is remembered and destroyed, so that the second sweep only has
	// to taint what is left standing.
	KindOfMaskType wanted(KindOfMaskType::kInit, RVA_0025C220_KIND_BIT,
		RVA_0025C220_KIND_BIT);
	PartitionFilterAcceptByKindOf firstFilter(wanted, KINDOFMASK_NONE);
	BfmeWideResult found = ThePartitionManager->bfmeForwardWideC(
		(Int)subject, range * BfmeRva0025C220RangeScale, 0, (Int)&firstFilter,
		1);
	_STL::set<Object *> *destroyed = new _STL::set<Object *>;
	Object *object;
	while (found.next(object))
	{
		if (object->getControllingPlayer() == owner->getControllingPlayer())
			continue;
		destroyed->insert(object);
		TheTerrainLogic->clearOne001AC3D0(&object->m_position,
			*(unsigned short *)&range);
		TheGameLogic->destroyObject(object);
	}

	// Second sweep: the same kind mask over the tighter circle, tainting
	// every survivor the first sweep did not claim.
	KindOfMaskType wantedToo(KindOfMaskType::kInit, RVA_0025C220_KIND_BIT,
		RVA_0025C220_KIND_BIT);
	PartitionFilterAcceptByKindOf secondFilter(wantedToo, KINDOFMASK_NONE);
	found = ThePartitionManager->bfmeForwardWideC((Int)subject,
		range * BfmeRva0025C220TaintScale, 0, (Int)&secondFilter, 1);
	while (found.next(object))
	{
		if (object->getControllingPlayer() == owner->getControllingPlayer())
			continue;
		if (destroyed->find(object) != destroyed->end())
			continue;
		Coord3D centre = object->m_position;
		TheTaintManager->bfmeApplyCircleWorld(&centre, range,
			(object->m_statusFlags & (1 << RVA_0025C220_STATUS_BIT)) == 0, 1);
	}

	// Close the power out on the ground the player clicked.
	TheTerrainLogic->adapter001A64F0((Int)subject, *(Int *)&range, 2);
	TheTerrainLogic->forward001A3190((Int)subject, *(Int *)&TheTerrainLogic,
		range + BfmeRva0025C220TaintMargin, 2);
	if (data->m_fxList != 0 && !data->m_fxList->bfmeIsBlocked())
		data->m_fxList->doFXPos(&subject->m_position, 0, 0, 0);
	if (data->m_thingFB != 0)
		data->m_thingFB->tellFB(m_object, &subject->m_position, 0, 0);

	Object *named = (Object *)applyAt0025C010(
		(Rva0025C7C0Location *)subject, data->m_templateName);
	if (named != 0)
		named->setStatus(StatusMaskType(StatusMaskType::kInit,
			RVA_0025C220_STATUS_BIT, 0), 1);
	TheTaintManager->bfmeApplyCircleWorld(&subject->m_position, range,
		0xff, 1);

	delete destroyed;
}
